import{_ as a,o as s,c as e,a2 as i}from"./chunks/framework.C4u7U0Dw.js";const _=JSON.parse('{"title":"第 3 章 我的工作方式：文件、命令与工具","description":"","frontmatter":{},"headers":[],"relativePath":"bluebook/第一篇 使用手册：先把我用起来/第 3 章 我的工作方式：文件、命令与工具.md","filePath":"bluebook/第一篇 使用手册：先把我用起来/第 3 章 我的工作方式：文件、命令与工具.md"}'),d={name:"bluebook/第一篇 使用手册：先把我用起来/第 3 章 我的工作方式：文件、命令与工具.md"};function l(n,t,o,r,p,h){return s(),e("div",null,[...t[0]||(t[0]=[i(`<h1 id="第-3-章-我的工作方式-文件、命令与工具" tabindex="-1">第 3 章 我的工作方式：文件、命令与工具 <a class="header-anchor" href="#第-3-章-我的工作方式-文件、命令与工具" aria-label="Permalink to &quot;第 3 章 我的工作方式：文件、命令与工具&quot;">​</a></h1><h2 id="_3-1-我的工具箱" tabindex="-1">3.1 我的工具箱 <a class="header-anchor" href="#_3-1-我的工具箱" aria-label="Permalink to &quot;3.1 我的工具箱&quot;">​</a></h2><p>我执行任务靠的不是&quot;魔法&quot;，而是一组明确的工具。知道有什么工具，你才知道能让我干什么：</p><table tabindex="0"><thead><tr><th>工具</th><th>干什么</th><th>什么时候用</th></tr></thead><tbody><tr><td>Read</td><td>读文件内容（带行号）</td><td>看源码、查日志、读配置</td></tr><tr><td>Write</td><td>创建/覆写文件</td><td>新建文档、生成代码</td></tr><tr><td>Edit</td><td>精确替换文件片段</td><td>改一行配置、修一个 bug</td></tr><tr><td>Glob</td><td>按文件名/扩展名找文件</td><td>找 <code>**/*.md</code>、<code>*.rs</code></td></tr><tr><td>Grep</td><td>按内容搜（正则）</td><td>搜报错、找函数定义</td></tr><tr><td>ExecCommand</td><td>执行 shell 命令</td><td>跑测试、装依赖、批量操作</td></tr><tr><td>Skill</td><td>调用预设技能</td><td>提交 commit、评审 PR</td></tr><tr><td>Spawn</td><td>开子代理并行干活</td><td>并行调研、分块生成</td></tr><tr><td>Team</td><td>组建多智能体团队</td><td>大项目多角色协作</td></tr></tbody></table><blockquote><p>工具分工的原则：<strong>有专用工具就不用裸命令。</strong> 找文件用 Glob，搜内容用 Grep，改文件用 Edit——而不是让我用命令行绕一圈。这既快又安全。</p></blockquote><h2 id="_3-2-我生活在工作目录里" tabindex="-1">3.2 我生活在工作目录里 <a class="header-anchor" href="#_3-2-我生活在工作目录里" aria-label="Permalink to &quot;3.2 我生活在工作目录里&quot;">​</a></h2><ul><li>我的所有文件操作，都发生在<strong>当前工作目录</strong>（以及你明确指定的路径）内。</li><li>你给我的相对路径，都基于这个目录解析。</li><li>如果你想让我访问别的目录，请给<strong>绝对路径</strong>。</li></ul><div class="language-powershell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 你的工作目录示例</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">C:\\Users\\</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">86175</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">\\AppData\\Roaming\\MomaWork\\MomaWork\\conversations\\momawork</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">rs</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">ebf4db3a</span></span></code></pre></div><h2 id="_3-3-命令执行-我说了算吗" tabindex="-1">3.3 命令执行：我说了算吗？ <a class="header-anchor" href="#_3-3-命令执行-我说了算吗" aria-label="Permalink to &quot;3.3 命令执行：我说了算吗？&quot;">​</a></h2><p>我能执行命令，但有三条铁律：</p><ol><li><strong>先读后改</strong>：编辑文件之前，我一定会先 Read，绝不盲改。</li><li><strong>危险操作先确认</strong>：删除、覆盖、<code>git push --force</code> 这类操作，我会先征得你同意。</li><li><strong>优先专用工具</strong>：能用工具库解决的，不绕 shell。</li></ol><h2 id="_3-4-一个具体例子-改-bug-的完整流程" tabindex="-1">3.4 一个具体例子：改 bug 的完整流程 <a class="header-anchor" href="#_3-4-一个具体例子-改-bug-的完整流程" aria-label="Permalink to &quot;3.4 一个具体例子：改 bug 的完整流程&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>你：&quot;src/app.py 第 42 行报 KeyError，帮我看看&quot;</span></span>
<span class="line"><span>我：Read src/app.py（先看现场）</span></span>
<span class="line"><span>  → Grep 搜索相关变量（定位问题）</span></span>
<span class="line"><span>  → Edit 精确修复（最小改动）</span></span>
<span class="line"><span>  → 让你检查 diff（可回退）</span></span>
<span class="line"><span>  → 必要时跑一条命令验证</span></span></code></pre></div><p>每一步都有中间产物，你可以随时叫停、检查、回退。<strong>这就是&quot;可检查的 AI&quot;。</strong></p><h2 id="_3-5-练习" tabindex="-1">3.5 练习 <a class="header-anchor" href="#_3-5-练习" aria-label="Permalink to &quot;3.5 练习&quot;">​</a></h2><ol><li>让我用 Glob 找出当前目录下所有 <code>.md</code> 文件。</li><li>让我用 Grep 搜一个词（比如你自己的名字），看看搜出什么。</li><li>给我写一个小文件，然后让我用 Edit 改其中一行。</li></ol><blockquote><p>小结：我越透明，你越放心；你越了解我的工具，越知道什么任务能交给我。</p></blockquote>`,17)])])}const k=a(d,[["render",l]]);export{_ as __pageData,k as default};
